{% extends "base.html" %}

{% block title %}トップページ{% endblock %}

{% block content %}
    <!-- メインコンテンツ -->
    <div class="container py-5">
      <h1 class="mb-4 text-center">👤 ユーザー管理</h1>

      <!-- ユーザー追加フォーム -->
      <div class="card mb-4 shadow-sm">
        <div class="card-body">
          <h5 class="card-title">ユーザー追加</h5>
          <form method="POST" action="{{ url_for('add_user') }}" class="row g-3">
            <div class="col-md-4">
              <input type="text" name="username" class="form-control" placeholder="ユーザー名" required>
            </div>
            <div class="col-md-4">
              <input type="password" name="password" class="form-control" placeholder="パスワード" required>
            </div>
            <div class="col-md-2">
              <select name="is_admin" class="form-select">
                <option value="0" selected>一般</option>
                <option value="1">管理者</option>
              </select>
            </div>
            <div class="col-md-2 d-grid">
              <button type="submit" class="btn btn-success">＋ 追加</button>
            </div>
          </form>
        </div>
      </div>

      <!-- ユーザー一覧 -->
      <div class="card shadow-sm">
        <div class="card-body">
          <h5 class="card-title">登録ユーザー一覧</h5>
          <table class="table table-striped table-hover align-middle">
            <thead class="table-dark">
              <tr>
                <th>ID</th>
                <th>ユーザー名</th>
                <th>権限</th>
                <th>操作</th>
              </tr>
            </thead>
            <tbody>
              {% for user in users %}
              <tr>
                <td>{{ user.id }}</td>
                <td>{{ user.username }}</td>
                <td>
                  {% if user.is_admin %}
                    <span class="badge bg-danger">管理者</span>
                  {% else %}
                    <span class="badge bg-secondary">一般</span>
                  {% endif %}
                </td>
                <td>
                  <div class="d-flex gap-2">
                    <!-- パスワード変更ボタン -->
                    <form method="POST" action="{{ url_for('change_password', user_id=user.id) }}" class="d-flex">
                      <input type="password" name="new_password" class="form-control form-control-sm me-2" placeholder="新パスワード" required>
                      <button type="submit" class="btn btn-warning btn-sm">🔑 変更</button>
                    </form>

                    <!-- 削除ボタン -->
                    <form method="POST" action="{{ url_for('delete_user', user_id=user.id) }}" onsubmit="return confirm('本当に削除しますか？');">
                      <button type="submit" class="btn btn-danger btn-sm">🗑 削除</button>
                    </form>
                  </div>
                </td>
              </tr>
              {% endfor %}
            </tbody>
          </table>
        </div>
      </div>
    </div>

    <!-- Bootstrap JS -->
    <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>
{% endblock %}


